import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1787179449000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n('<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="startup" tabindex="-1">Startup <a class="header-anchor" href="#startup" aria-label="Permalink to “Startup”">​</a></h2><h3 id="a-server-s-path-returns-503-right-after-starting" tabindex="-1">A server&#39;s path returns 503 right after starting <a class="header-anchor" href="#a-server-s-path-returns-503-right-after-starting" aria-label="Permalink to “A server&#39;s path returns 503 right after starting”">​</a></h3><p>Expected, for a while. Children are started in the background and their paths answer <code>503</code> until the MCP handshake completes. A server that downloads a package on first run can take minutes on a slow machine.</p><p>Check <code>docker logs mcp-hub</code> and <code>/health</code>. If the state stays <code>down</code> and the <code>restarts</code> counter climbs, that child is crash-looping — its own stderr in the container log will say why.</p><h3 id="the-hub-will-not-start-undefined-environment-variable-in-config" tabindex="-1">The hub will not start: <code>Undefined environment variable in config</code> <a class="header-anchor" href="#the-hub-will-not-start-undefined-environment-variable-in-config" aria-label="Permalink to “The hub will not start: Undefined environment variable in config”">​</a></h3><p><code>${VAR}</code> may expand to an <em>empty</em> value, but a variable that is not defined at all aborts parsing of the whole file — one entry takes every server with it.</p><p>Pass the variable through explicitly in your Compose file, even as an empty string:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">environment</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">:</span></span>\n<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  SOME_TOKEN</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;${SOME_TOKEN:-}&quot;</span></span></code></pre></div><h3 id="eacces-writing-data-jwt-key-pem" tabindex="-1"><code>EACCES</code> writing <code>/data/jwt-key.pem</code> <a class="header-anchor" href="#eacces-writing-data-jwt-key-pem" aria-label="Permalink to “EACCES writing /data/jwt-key.pem”">​</a></h3><p>The container runs as uid 1000 and a bind-mounted directory keeps the host&#39;s ownership:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">sudo</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> chown</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -R</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> 1000:1000</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> ./data</span></span></code></pre></div><p><code>chown</code> in the Dockerfile only affects the image layer, not your bind mount. A named volume inherits the image&#39;s ownership and avoids this entirely.</p><h3 id="the-hub-logs-a-warning-about-trusted-proxies" tabindex="-1">The hub logs a warning about <code>TRUSTED_PROXIES</code> <a class="header-anchor" href="#the-hub-logs-a-warning-about-trusted-proxies" aria-label="Permalink to “The hub logs a warning about TRUSTED_PROXIES”">​</a></h3><p>It is unset, so every request appears to come from the reverse proxy and per-IP rate limiting collapses into one global counter. Set it to your proxy&#39;s address — see <a href="/guide/security#trusted-proxies">Security</a>.</p><h2 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to “Authorization”">​</a></h2><h3 id="the-client-is-redirected-to-http-instead-of-https" tabindex="-1">The client is redirected to <code>http://…</code> instead of <code>https://…</code> <a class="header-anchor" href="#the-client-is-redirected-to-http-instead-of-https" aria-label="Permalink to “The client is redirected to http://… instead of https://…”">​</a></h3><p><code>EXTERNAL_URL</code> must be the exact public HTTPS origin, with no trailing path, and the proxy has to pass <code>X-Forwarded-Proto</code>. Every OAuth metadata document and redirect is built from that value.</p><h3 id="every-connector-suddenly-has-to-authorize-again" tabindex="-1">Every connector suddenly has to authorize again <a class="header-anchor" href="#every-connector-suddenly-has-to-authorize-again" aria-label="Permalink to “Every connector suddenly has to authorize again”">​</a></h3><p>Three causes, in order of likelihood:</p><ol><li><strong><code>/data</code> was recreated.</strong> The JWT key and all client records live there. A fresh directory means a fresh authorization server as far as clients are concerned.</li><li><strong>You upgraded to 0.5.0 or later.</strong> Resource binding is on by default now, which intentionally retires tokens issued without a resource. It is a one-time cost; <code>RESOURCE_BOUND_TOKENS=false</code> postpones it.</li><li><strong>A client was revoked</strong> with <code>mcp-hub-admin clients revoke</code>.</li></ol><h3 id="i-get-an-approve-deny-page-instead-of-the-password-prompt" tabindex="-1">I get an <em>Approve / Deny</em> page instead of the password prompt <a class="header-anchor" href="#i-get-an-approve-deny-page-instead-of-the-password-prompt" aria-label="Permalink to “I get an Approve / Deny page instead of the password prompt”">​</a></h3><p>That is the intended behaviour when a login session is still valid (30 minutes) and a client the hub has not seen before asks for authorization. The hub knows who you are but will not hand a code to an unconfirmed client.</p><p>If you did not initiate the request, deny it.</p><h3 id="a-client-keeps-asking-for-the-password" tabindex="-1">A client keeps asking for the password <a class="header-anchor" href="#a-client-keeps-asking-for-the-password" aria-label="Permalink to “A client keeps asking for the password”">​</a></h3><p>An approval is bound to the client ID <strong>and</strong> the redirect URI it was approved for. A client that changes its redirect target counts as new. Loopback URIs (<code>http://127.0.0.1:&lt;port&gt;/…</code>) match regardless of port, so a desktop client picking a fresh port each time is not the cause.</p><p>Check <code>mcp-hub-admin clients list</code> — if the same client name appears many times with different IDs, the client is re-registering instead of persisting its credentials.</p><h3 id="health-returns-401" tabindex="-1"><code>/health</code> returns 401 <a class="header-anchor" href="#health-returns-401" aria-label="Permalink to “/health returns 401”">​</a></h3><p>By design since v0.3.0: <code>/health</code> exposes per-server state and sits behind a bearer token. Point liveness monitoring at <code>/livez</code>, which is unauthenticated and returns <code>{&quot;status&quot;:&quot;ok&quot;}</code>.</p><p>Since 0.5.0 the token also has to be the one for <code>/hub</code> — <code>/health</code> lists every server, so a token bound to a single server does not cover it.</p><h3 id="fail2ban-banned-my-own-clients" tabindex="-1">fail2ban banned my own clients <a class="header-anchor" href="#fail2ban-banned-my-own-clients" aria-label="Permalink to “fail2ban banned my own clients”">​</a></h3><p>A generic &quot;ban on repeated 401&quot; jail reading the reverse proxy&#39;s access log will do this: the MCP authorization flow produces legitimate 401 responses on every new connection. Exclude the hub&#39;s vhost from such jails, and use the purpose-built <a href="/guide/deployment#fail2ban"><code>mcp-hub-auth</code> filter</a>, which matches the hub&#39;s own log lines instead.</p><h2 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to “Runtime”">​</a></h2><h3 id="tool-calls-fail-after-about-a-minute" tabindex="-1">Tool calls fail after about a minute <a class="header-anchor" href="#tool-calls-fail-after-about-a-minute" aria-label="Permalink to “Tool calls fail after about a minute”">​</a></h3><p>Your reverse proxy is cutting the request. MCP tool calls are long-running; the hub allows 310 seconds and its internal call timeout is 5 minutes (reset on progress notifications). Raise <code>proxy_read_timeout</code> / the equivalent to at least 330 seconds.</p><h3 id="requests-get-429-with-mcp-request-rate-limit-exceeded" tabindex="-1">Requests get <code>429</code> with <code>MCP request rate limit exceeded</code> <a class="header-anchor" href="#requests-get-429-with-mcp-request-rate-limit-exceeded" aria-label="Permalink to “Requests get 429 with MCP request rate limit exceeded”">​</a></h3><p>The per-client gate: <code>MCP_REQUESTS_PER_MINUTE</code> (default 120) and <code>MCP_MAX_CONCURRENT_REQUESTS</code> (default 4), counted <strong>per OAuth client</strong>. Raise them if a legitimate client needs more.</p><h3 id="editing-mcp-json-does-nothing" tabindex="-1">Editing <code>mcp.json</code> does nothing <a class="header-anchor" href="#editing-mcp-json-does-nothing" aria-label="Permalink to “Editing mcp.json does nothing”">​</a></h3><p>With the recommended directory mount (<code>./config:/config:ro</code>) any host-side edit is picked up within a few seconds. If nothing happens, check two things:</p><ol><li><strong>A single-file bind mount plus an editor that saves via rename.</strong> Most editors write a temp file and rename it over the original — that creates a new inode, and a <code>-v ./mcp.json:/config/mcp.json</code> mount keeps pointing at the old one, so the container never sees the edit (compare <code>md5sum mcp.json</code> on the host with <code>docker exec mcp-hub md5sum /config/mcp.json</code>). The hub logs a <code>single-file bind mount</code> warning at startup for this setup. Immediate fix: recreate <strong>both</strong> the hub and the docker-proxy container; lasting fix: mount the directory.</li><li><strong>A broken edit.</strong> Look for <code>ignoring broken config update: …</code> in the log: an edit that does not parse is rejected and the previous configuration stays active.</li></ol><h3 id="notifications-from-a-server-never-arrive" tabindex="-1">Notifications from a server never arrive <a class="header-anchor" href="#notifications-from-a-server-never-arrive" aria-label="Permalink to “Notifications from a server never arrive”">​</a></h3><p>The transport is stateless, so server-initiated messages — <code>listChanged</code>, resource subscriptions, sampling — are not delivered to clients. This is a deliberate trade for not leaking session state on every client reconnect. Tool, resource and prompt request/response traffic is unaffected.</p><h3 id="a-sandboxed-server-is-refused-with-403-does-not-match-the-configuration" tabindex="-1">A sandboxed server is refused with <code>403 … does not match the configuration</code> <a class="header-anchor" href="#a-sandboxed-server-is-refused-with-403-does-not-match-the-configuration" aria-label="Permalink to “A sandboxed server is refused with 403 … does not match the configuration”">​</a></h3><p>The <a href="/guide/sandboxing#the-policy-proxy">docker proxy</a> derives its policy from <code>mcp.json</code>, and both it and the hub poll that file independently. Right after an edit, the hub can send a create request built from the new configuration while the proxy still holds the old one. The server goes <code>down</code> and the supervisor retries — it resolves itself within seconds.</p><p>If it does not, the two are not reading the same file: check that both containers mount the same config directory, and that they run the same image version.</p><h3 id="a-sandboxed-server-never-comes-up-and-the-log-shows-not-json" tabindex="-1">A sandboxed server never comes up and the log shows <code>not JSON</code> <a class="header-anchor" href="#a-sandboxed-server-never-comes-up-and-the-log-shows-not-json" aria-label="Permalink to “A sandboxed server never comes up and the log shows not JSON”">​</a></h3><p>The server writes to <strong>stdout</strong>, which under stdio is the protocol channel. Its logging has to go to stderr; the hub prefixes that with the server name and passes it through to its own stderr.</p><h3 id="a-server-name-is-rejected" tabindex="-1">A server name is rejected <a class="header-anchor" href="#a-server-name-is-rejected" aria-label="Permalink to “A server name is rejected”">​</a></h3><p>Names must match <code>[a-zA-Z0-9_-]+</code>, and these are reserved because the hub serves them itself: <code>mcp</code>, <code>hub</code>, <code>authorize</code>, <code>token</code>, <code>register</code>, <code>login</code>, <code>consent</code>, <code>health</code>, <code>livez</code>, <code>revoke</code>, <code>.well-known</code>.</p><h3 id="a-server-shows-sleeping-the-first-tool-call-is-slow" tabindex="-1">A server shows <code>sleeping</code> / the first tool call is slow <a class="header-anchor" href="#a-server-shows-sleeping-the-first-tool-call-is-slow" aria-label="Permalink to “A server shows sleeping / the first tool call is slow”">​</a></h3><p>Working as intended: stdio and docker servers run <a href="/guide/on-demand">on demand</a> by default and sleep after 60 minutes of inactivity. The first call to a sleeping server pays its cold start; everything after that is normal. If one server&#39;s cold start bothers you, give it <code>&quot;keepAlive&quot;: true</code>; to disable the feature entirely, set <code>IDLE_TIMEOUT_MINUTES: &quot;0&quot;</code>.</p><h3 id="a-crashed-server-stopped-restarting" tabindex="-1">A crashed server stopped restarting <a class="header-anchor" href="#a-crashed-server-stopped-restarting" aria-label="Permalink to “A crashed server stopped restarting”">​</a></h3><p>An on-demand server that fails five restarts in a row <strong>without being used</strong> goes back to <code>sleeping</code> instead of crash-looping forever — its <code>lastError</code> stays visible in <code>list_servers</code> and <code>/health</code>. The next tool call (or <code>wake_server</code>) tries a fresh start. Servers with <code>keepAlive: true</code> keep the endless-backoff behaviour.</p><h2 id="operating" tabindex="-1">Operating <a class="header-anchor" href="#operating" aria-label="Permalink to “Operating”">​</a></h2><h3 id="how-do-i-update" tabindex="-1">How do I update? <a class="header-anchor" href="#how-do-i-update" aria-label="Permalink to “How do I update?”">​</a></h3><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">docker</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> compose</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> pull</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> &amp;&amp; </span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">docker</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> compose</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> up</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -d</span></span></code></pre></div><p>Pin a version tag rather than <code>latest</code> so this happens when you decide. Read the <a href="/reference/changelog">changelog</a> first — <code>0.3.0</code> moved <code>/health</code> behind authentication, which breaks external monitors that polled it.</p><h3 id="can-several-people-use-one-hub" tabindex="-1">Can several people use one hub? <a class="header-anchor" href="#can-several-people-use-one-hub" aria-label="Permalink to “Can several people use one hub?”">​</a></h3><p>Not meaningfully. There is one password and no user accounts; anyone who knows it can approve a client and reach every server. For roles, audit trails or SSO, use something built for that — see <a href="/guide/comparison">Comparison</a>.</p><h3 id="can-i-hide-a-server-from-hub-but-keep-it-reachable" tabindex="-1">Can I hide a server from <code>/hub</code> but keep it reachable? <a class="header-anchor" href="#can-i-hide-a-server-from-hub-but-keep-it-reachable" aria-label="Permalink to “Can I hide a server from /hub but keep it reachable?”">​</a></h3><p>Yes: <code>&quot;hub&quot;: false</code>. Its own path keeps working. This is the usual setup for servers you register as their own connector anyway, so they are not offered twice.</p><h3 id="is-a-mixed-setup-possible-—-some-servers-isolated" tabindex="-1">Is a mixed setup possible — some servers isolated? <a class="header-anchor" href="#is-a-mixed-setup-possible-—-some-servers-isolated" aria-label="Permalink to “Is a mixed setup possible — some servers isolated?”">​</a></h3><p>That is the recommended shape when trust levels differ. Run the sensitive servers in their own containers and add them to the hub as <code>type: &quot;http&quot;</code> entries. Clients see one endpoint either way, and a remote upstream has no access to the hub&#39;s process or files.</p><h3 id="where-do-i-report-a-security-issue" tabindex="-1">Where do I report a security issue? <a class="header-anchor" href="#where-do-i-report-a-security-issue" aria-label="Permalink to “Where do I report a security issue?”">​</a></h3><p><a href="https://github.com/ni-c/mcp-hub/security/advisories/new" target="_blank" rel="noreferrer">GitHub private vulnerability reporting</a>. Please do not open a public issue, and leave real credentials and hostnames out of the report.</p>',65)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};